  1→// MCP Server Integration for Unified Safecast Server
  2→// Starts MCP server on separate port (default 3333)
  3→// Requires: PostgreSQL (main DB), DuckDB (optional for analytics), ANTHROPIC_API_KEY (optional, for web chat)
  4→
  5→package main
  6→
  7→import (
  8→	"bytes"
  9→	"context"
 10→	_ "embed"
 11→	"encoding/json"
 12→	"fmt"
 13→	"io"
 14→	"log"
 15→	"net/http"
 16→	"os"
 17→	"path/filepath"
 18→	"strings"
 19→	"time"
 20→
 21→	mcpclient "github.com/mark3labs/mcp-go/client"
 22→	"github.com/mark3labs/mcp-go/mcp"
 23→	"github.com/mark3labs/mcp-go/server"
 24→	httpSwagger "github.com/swaggo/http-swagger"
 25→	"safecast-new-map/cmd/unified-server/model-adapter"
 26→)
 27→
 28→var (
 29→	mcpModelAdapter *modeladapter.Adapter
 30→	mcpHintsLoader  *modeladapter.HintsLoader
 31→)
 32→
 33→//go:embed static/index.html
 34→var webChatIndexHTML []byte
 35→
 36→//go:embed static/safecast-square-ct.png
 37→var webChatLogoPNG []byte
 38→
 39→const webChatSystemPrompt = `Safecast radiation monitoring assistant with REAL-TIME sensor data and historical archives.`
 40→
 41→// Anthropic API types
 42→type anthropicTool struct {
 43→	Name        string          `json:"name"`
 44→	Description string          `json:"description"`
 45→	InputSchema json.RawMessage `json:"input_schema"`
 46→}
 47→
 48→type contentBlock struct {
 49→	Type      string          `json:"type"`
 50→	Text      string          `json:"text,omitempty"`
 51→	ID        string          `json:"id,omitempty"`
 52→	Name      string          `json:"name,omitempty"`
 53→	Input     json.RawMessage `json:"input,omitempty"`
 54→	ToolUseID string          `json:"tool_use_id,omitempty"`
 55→	Content   string          `json:"content,omitempty"`
 56→}
 57→
 58→type anthropicMessage struct {
 59→	Role    string      `json:"role"`
 60→	Content interface{} `json:"content"`
 61→}
 62→
 63→type anthropicRequest struct {
 64→	Model     string             `json:"model"`
 65→	MaxTokens int                `json:"max_tokens"`
 66→	System    string             `json:"system"`
 67→	Messages  []anthropicMessage `json:"messages"`
 68→	Tools     []anthropicTool    `json:"tools,omitempty"`
 69→}
 70→
 71→type anthropicResponse struct {
 72→	Content    []contentBlock `json:"content"`
 73→	StopReason string         `json:"stop_reason"`
 74→	Error      *struct {
 75→		Type    string `json:"type"`
 76→		Message string `json:"message"`
 77→	} `json:"error,omitempty"`
 78→}
 79→
 80→// Streaming helpers
 81→type chunk struct {
 82→	Type  string `json:"type"`
 83→	Text  string `json:"text,omitempty"`
 84→	Error string `json:"error,omitempty"`
 85→}
 86→
 87→func writeChunk(w http.ResponseWriter, c chunk) {
 88→	data, _ := json.Marshal(c)
 89→	data = append(data, '\n')
 90→	w.Write(data)
 91→	if f, ok := w.(http.Flusher); ok {
 92→		f.Flush()
 93→	}
 94→}
 95→
 96→func writeChunkBuffered(w http.ResponseWriter, c chunk, buffer *[]chunk, useBuffer bool) {
 97→	if useBuffer {
 98→		*buffer = append(*buffer, c)
 99→	} else {
100→		writeChunk(w, c)
101→	}
102→}
103→
104→func flushBuffer(w http.ResponseWriter, buffer []chunk) {
105→	for _, c := range buffer {
106→		writeChunk(w, c)
107→	}
108→}
109→
110→func callAnthropic(ctx context.Context, apiKey, model string, messages []anthropicMessage, tools []anthropicTool) (*anthropicResponse, error) {
111→	reqBody := anthropicRequest{
112→		Model:     model,
113→		MaxTokens: 4096,
114→		System:    webChatSystemPrompt,
115→		Messages:  messages,
116→		Tools:     tools,
117→	}
118→	body, err := json.Marshal(reqBody)
119→	if err != nil {
120→		return nil, err
121→	}
122→
123→	req, err := http.NewRequestWithContext(ctx, http.MethodPost, "https://api.anthropic.com/v1/messages", bytes.NewReader(body))
124→	if err != nil {
125→		return nil, err
126→	}
127→	req.Header.Set("Content-Type", "application/json")
128→	req.Header.Set("x-api-key", apiKey)
129→	req.Header.Set("anthropic-version", "2023-06-01")
130→
131→	resp, err := http.DefaultClient.Do(req)
132→	if err != nil {
133→		return nil, err
134→	}
135→	defer resp.Body.Close()
136→
137→	raw, err := io.ReadAll(resp.Body)
138→	if err != nil {
139→		return nil, err
140→	}
141→
142→	var ar anthropicResponse
143→	if err := json.Unmarshal(raw, &ar); err != nil {
144→		return nil, fmt.Errorf("parse response: %w", err)
145→	}
146→	if ar.Error != nil {
147→		return nil, fmt.Errorf("anthropic %s: %s", ar.Error.Type, ar.Error.Message)
148→	}
149→	return &ar, nil
150→}
151→
152→func mcpToolsToAnthropic(tools []mcp.Tool) []anthropicTool {
153→	var out []anthropicTool
154→	for _, t := range tools {
155→		schema, _ := json.Marshal(t.InputSchema)
156→		out = append(out, anthropicTool{
157→			Name:        t.Name,
158→			Description: t.Description,
159→			InputSchema: json.RawMessage(schema),
160→		})
161→	}
162→	return out
163→}
164→
165→func handleWebChat(mcpURL, apiKey, model string) http.HandlerFunc {
166→	return func(w http.ResponseWriter, r *http.Request) {
167→		w.Header().Set("Access-Control-Allow-Origin", "*")
168→		w.Header().Set("Access-Control-Allow-Methods", "POST, OPTIONS")
169→		w.Header().Set("Access-Control-Allow-Headers", "Content-Type")
170→		if r.Method == http.MethodOptions {
171→			w.WriteHeader(http.StatusNoContent)
172→			return
173→		}
174→
175→		isCloudFront := r.Header.Get("CloudFront-Viewer-Country") != "" ||
176→			r.Header.Get("CloudFront-Forwarded-Proto") != "" ||
177→			r.Header.Get("X-Amz-Cf-Id") != ""
178→
179→		w.Header().Set("Content-Type", "application/x-ndjson")
180→		if !isCloudFront {
181→			w.Header().Set("Transfer-Encoding", "chunked")
182→			w.Header().Set("X-Accel-Buffering", "no")
183→		}
184→		w.Header().Set("Cache-Control", "no-cache, no-store")
185→
186→		var buffer []chunk
187→		ctx := r.Context()
188→
189→		var chatReq struct {
190→			Message         string             `json:"message"`
191→			History         []anthropicMessage `json:"history,omitempty"`
192→			Source          string             `json:"source,omitempty"`
193→			ClientTimestamp string             `json:"client_timestamp,omitempty"`
194→		}
195→		if err := json.NewDecoder(r.Body).Decode(&chatReq); err != nil || chatReq.Message == "" {
196→			w.WriteHeader(http.StatusBadRequest)
197→			writeChunkBuffered(w, chunk{Type: "error", Error: "invalid request: message required"}, &buffer, isCloudFront)
198→			if isCloudFront {
199→				flushBuffer(w, buffer)
200→			}
201→			return
202→		}
203→
204→		// Default source if not provided by frontend
205→		source := chatReq.Source
206→		if source == "" {
207→			source = "web-chat"
208→		}
209→		chatRowID := logChatQuestion(r, chatReq.Message, source, model, "", len(chatReq.History), chatReq.ClientTimestamp)
210→		var answerText strings.Builder
211→
212→		mc, err := mcpclient.NewStreamableHttpClient(mcpURL)
213→		if err != nil {
214→			writeChunkBuffered(w, chunk{Type: "error", Error: fmt.Sprintf("MCP connect: %v", err)}, &buffer, isCloudFront)
215→			if isCloudFront {
216→				flushBuffer(w, buffer)
217→			}
218→			return
219→		}
220→		defer mc.Close()
221→
222→		if _, err := mc.Initialize(ctx, mcp.InitializeRequest{
223→			Params: mcp.InitializeParams{
224→				ProtocolVersion: mcp.LATEST_PROTOCOL_VERSION,
225→				ClientInfo:      mcp.Implementation{Name: "safecast-web-chat", Version: "1.0.0"},
226→			},
227→		}); err != nil {
228→			writeChunkBuffered(w, chunk{Type: "error", Error: fmt.Sprintf("MCP init: %v", err)}, &buffer, isCloudFront)
229→			if isCloudFront {
230→				flushBuffer(w, buffer)
231→			}
232→			return
233→		}
234→
235→		toolsResult, err := mc.ListTools(ctx, mcp.ListToolsRequest{})
236→		if err != nil {
237→			writeChunkBuffered(w, chunk{Type: "error", Error: fmt.Sprintf("list tools: %v", err)}, &buffer, isCloudFront)
238→			if isCloudFront {
239→				flushBuffer(w, buffer)
240→			}
241→			return
242→		}
243→		tools := mcpToolsToAnthropic(toolsResult.Tools)
244→
245→		messages := chatReq.History
246→		if messages == nil {
247→			messages = []anthropicMessage{}
248→		}
249→		messages = append(messages, anthropicMessage{Role: "user", Content: chatReq.Message})
250→
251→		for {
252→			resp, err := callAnthropic(ctx, apiKey, model, messages, tools)
253→			if err != nil {
254→				writeChunkBuffered(w, chunk{Type: "error", Error: err.Error()}, &buffer, isCloudFront)
255→				if isCloudFront {
256→					flushBuffer(w, buffer)
257→				}
258→				return
259→			}
260→
261→			messages = append(messages, anthropicMessage{
262→				Role:    "assistant",
263→				Content: resp.Content,
264→			})
265→
266→			var toolUses []contentBlock
267→			for _, block := range resp.Content {
268→				switch block.Type {
269→				case "text":
270→					answerText.WriteString(block.Text)
271→					writeChunkBuffered(w, chunk{Type: "text", Text: block.Text}, &buffer, isCloudFront)
272→				case "tool_use":
273→					toolUses = append(toolUses, block)
274→				}
275→			}
276→
277→			if resp.StopReason == "end_turn" || len(toolUses) == 0 {
278→				break
279→			}
280→
281→			var toolResults []contentBlock
282→			for _, tu := range toolUses {
283→				var args map[string]any
284→				_ = json.Unmarshal(tu.Input, &args)
285→
286→				callReq := mcp.CallToolRequest{}
287→				callReq.Params.Name = tu.Name
288→				callReq.Params.Arguments = args
289→
290→				var resultText string
291→				toolResult, err := mc.CallTool(ctx, callReq)
292→				if err != nil {
293→					resultText = fmt.Sprintf("tool error: %v", err)
294→				} else {
295→					for _, c := range toolResult.Content {
296→						if tc, ok := c.(mcp.TextContent); ok {
297→							resultText += tc.Text
298→						}
299→					}
300→				}
301→
302→				toolResults = append(toolResults, contentBlock{
303→					Type:      "tool_result",
304→					ToolUseID: tu.ID,
305→					Content:   resultText,
306→				})
307→			}
308→
309→			messages = append(messages, anthropicMessage{
310→				Role:    "user",
311→				Content: toolResults,
312→			})
313→		}
314→
315→		logChatAnswer(chatRowID, strings.TrimSpace(answerText.String()))
316→
317→		writeChunkBuffered(w, chunk{Type: "done"}, &buffer, isCloudFront)
318→		if isCloudFront {
319→			flushBuffer(w, buffer)
320→		}
321→	}
322→}
