470→func instrumentMCP(
471→	name string,
472→	h func(context.Context, mcp.CallToolRequest) (*mcp.CallToolResult, error),
473→) func(context.Context, mcp.CallToolRequest) (*mcp.CallToolResult, error) {
474→	return func(ctx context.Context, req mcp.CallToolRequest) (*mcp.CallToolResult, error) {
475→		start := time.Now()
476→
477→		userID := ""
478→		userEmail := ""
479→		if req.Params.Arguments != nil {
480→			if args, ok := req.Params.Arguments.(map[string]any); ok {
481→				if v, ok := args["user_id"].(string); ok {
482→					userID = v
483→				}
484→				if v, ok := args["user_email"].(string); ok {
485→					userEmail = v
486→				}
487→			}
488→		}
489→
490→		res, err := h(ctx, req)
491→
492→		if mcpModelAdapter != nil && res != nil {
493→			res = mcpModelAdapter.EnrichResult(ctx, res)
494→		}
495→
496→		duration := time.Since(start)
497→
498→		resultCount := 0
499→		if res != nil {
500→			resultCount = len(res.Content)
501→		}
502→
503→		args := map[string]any{}
504→		if req.Params.Arguments != nil {
505→			if argsMap, ok := req.Params.Arguments.(map[string]any); ok {
506→				args = argsMap
507→			}
508→		}
509→
510→		LogQueryAsync(name, args, resultCount, duration, "unified-server")
511→
512→		logAISessionWithUser(
513→			name,
514→			"",
515→			duration.Milliseconds(),
516→			err,
517→			userID,
518→			userEmail,
519→		)
520→
521→		return res, err
522→	}
523→}
