11→// queryRows executes a query on PostgreSQL and returns results as a slice of maps
12→func queryRows(ctx context.Context, query string, args ...any) ([]map[string]any, error) {
13→	if db == nil || db.DB == nil {
14→		return nil, sql.ErrNoRows
15→	}
16→
17→	rows, err := db.DB.QueryContext(ctx, query, args...)
18→	if err != nil {
19→		return nil, err
20→	}
21→	defer rows.Close()
22→
23→	columns, err := rows.Columns()
24→	if err != nil {
25→		return nil, err
26→	}
27→
28→	var results []map[string]any
29→	for rows.Next() {
30→		values := make([]any, len(columns))
31→		valuePtrs := make([]any, len(columns))
32→		for i := range values {
33→			valuePtrs[i] = &values[i]
34→		}
35→
36→		if err := rows.Scan(valuePtrs...); err != nil {
37→			return nil, err
38→		}
39→
40→		row := make(map[string]any, len(columns))
41→		for i, col := range columns {
42→			row[col] = values[i]
43→		}
44→		results = append(results, row)
45→	}
46→
47→	return results, rows.Err()
48→}
49→
50→// queryRow executes a query on PostgreSQL and returns a single row as a map
51→func queryRow(ctx context.Context, query string, args ...any) (map[string]any, error) {
