// Chat question logging to DuckDB analytics
// Captures user questions from the web-chat and map widget with request metadata

package main

import (
	"log"
	"net"
	"net/http"
	"strings"
)

// logChatQuestion logs a user's chat question to DuckDB and returns the row ID.
// The returned ID can be passed to logChatAnswer to attach the AI response.
func logChatQuestion(r *http.Request, question, source, model, sessionID string, historyLen int, clientTimestamp string) int64 {
	if !duckDBAvailable() {
		return 0
	}

	if len(question) > 5000 {
		question = question[:5000]
	}

	ip := getClientIP(r)
	ua := r.Header.Get("User-Agent")
	isMobile, osName, browser := parseUserAgent(ua)
	country := r.Header.Get("CloudFront-Viewer-Country")
	acceptLang := r.Header.Get("Accept-Language")
	if len(acceptLang) > 200 {
		acceptLang = acceptLang[:200]
	}
	referer := r.Header.Get("Referer")
	isCloudFront := r.Header.Get("CloudFront-Viewer-Country") != "" ||
		r.Header.Get("CloudFront-Forwarded-Proto") != "" ||
		r.Header.Get("X-Amz-Cf-Id") != ""

	// Parse client timestamp; use nil if not provided or invalid
	var clientTS interface{}
	if clientTimestamp != "" {
		clientTS = clientTimestamp
	}

	var id int64
	err := duckDB.QueryRow(`
		INSERT INTO chat_questions (
			question, source, ip_address, user_agent, is_mobile,
			os, browser, country, accept_language, referer,
			session_id, history_length, model, cloudfront, client_timestamp
		) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
		RETURNING id`,
		question, source, ip, ua, isMobile,
		osName, browser, country, acceptLang, referer,
		sessionID, historyLen, model, isCloudFront, clientTS,
	).Scan(&id)
	if err != nil {
		log.Printf("chat_questions insert error: %v", err)
		return 0
	}
	return id
}

// logChatAnswer updates a chat_questions row with the AI's response (async).
func logChatAnswer(rowID int64, answer string) {
	if !duckDBAvailable() || rowID == 0 {
		return
	}
	if len(answer) > 50000 {
		answer = answer[:50000]
	}
	go func() {
		_, err := duckDB.Exec(`UPDATE chat_questions SET answer = ? WHERE id = ?`, answer, rowID)
		if err != nil {
			log.Printf("chat_questions answer update error: %v", err)
		}
	}()
}

// getClientIP extracts the client IP from the request, respecting proxy headers.
func getClientIP(r *http.Request) string {
	// X-Forwarded-For may contain multiple IPs: client, proxy1, proxy2
	if xff := r.Header.Get("X-Forwarded-For"); xff != "" {
		parts := strings.SplitN(xff, ",", 2)
		ip := strings.TrimSpace(parts[0])
		if ip != "" {
			return ip
		}
	}
	if xri := r.Header.Get("X-Real-IP"); xri != "" {
		return strings.TrimSpace(xri)
	}
	host, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		return r.RemoteAddr
	}
	return host
}

// parseUserAgent extracts mobile/desktop, OS, and browser from User-Agent string.
func parseUserAgent(ua string) (isMobile bool, osName, browser string) {
	lower := strings.ToLower(ua)

	// Mobile detection
	isMobile = strings.Contains(lower, "mobile") ||
		strings.Contains(lower, "android") && !strings.Contains(lower, "tablet") ||
		strings.Contains(lower, "iphone") ||
		strings.Contains(lower, "ipod")

	// OS detection
	switch {
	case strings.Contains(lower, "iphone") || strings.Contains(lower, "ipad") || strings.Contains(lower, "ipod"):
		osName = "iOS"
	case strings.Contains(lower, "android"):
		osName = "Android"
	case strings.Contains(lower, "windows"):
		osName = "Windows"
	case strings.Contains(lower, "macintosh") || strings.Contains(lower, "mac os"):
		osName = "macOS"
	case strings.Contains(lower, "linux"):
		osName = "Linux"
	case strings.Contains(lower, "cros"):
		osName = "ChromeOS"
	default:
		osName = "Unknown"
	}

	// Browser detection (order matters — check specific before generic)
	switch {
	case strings.Contains(lower, "edg/") || strings.Contains(lower, "edge/"):
		browser = "Edge"
	case strings.Contains(lower, "opr/") || strings.Contains(lower, "opera"):
		browser = "Opera"
	case strings.Contains(lower, "firefox/"):
		browser = "Firefox"
	case strings.Contains(lower, "chrome/") && !strings.Contains(lower, "chromium"):
		browser = "Chrome"
	case strings.Contains(lower, "safari/") && !strings.Contains(lower, "chrome"):
		browser = "Safari"
	case strings.Contains(lower, "chromium"):
		browser = "Chromium"
	default:
		browser = "Unknown"
	}

	return
}

// DuckDB Analytics Initialization for Unified Server
// Uses DuckLake with PostgreSQL catalog for shared analytics across all services

package main

import (
	"database/sql"
	"fmt"
	"log"
	"os"
	"strings"

	_ "github.com/duckdb/duckdb-go/v2"
)

var duckDB *sql.DB

// initDuckDBAnalytics initializes DuckDB with DuckLake catalog backed by PostgreSQL.
// This allows multiple services to share the same analytics tables concurrently.
func initDuckDBAnalytics() error {
	// Open in-memory DuckDB — all persistent data lives in DuckLake (PostgreSQL + Parquet)
	var err error
	duckDB, err = sql.Open("duckdb", "")
	if err != nil {
		return fmt.Errorf("failed to open duckdb: %w", err)
	}

	duckDB.SetMaxOpenConns(1)
	duckDB.SetMaxIdleConns(1)
	duckDB.SetConnMaxLifetime(0)

	if err := duckDB.Ping(); err != nil {
		return fmt.Errorf("failed to ping duckdb: %w", err)
	}

	log.Println("DuckDB initialized (in-memory)")

	// Install and load required extensions
	for _, ext := range []string{"ducklake", "postgres"} {
		if _, err := duckDB.Exec(fmt.Sprintf("INSTALL %s;", ext)); err != nil {
			log.Printf("Warning: INSTALL %s failed: %v", ext, err)
		}
		if _, err := duckDB.Exec(fmt.Sprintf("LOAD %s;", ext)); err != nil {
			return fmt.Errorf("LOAD %s: %w", ext, err)
		}
	}

	// Attach DuckLake catalog via PostgreSQL
	ducklakePGURL := os.Getenv("DUCKLAKE_PG_URL")
	if ducklakePGURL == "" {
		ducklakePGURL = "dbname=ducklake_catalog host=localhost user=postgres password=LvjxpY1xNTijMT"
	}
	dataPath := os.Getenv("DUCKLAKE_DATA_PATH")
	if dataPath == "" {
		dataPath = "/var/lib/safecast/ducklake/"
	}

	attachQuery := fmt.Sprintf(
		"ATTACH 'ducklake:postgres:%s' AS analytics (DATA_PATH '%s');",
		ducklakePGURL, dataPath,
	)
	if _, err := duckDB.Exec(attachQuery); err != nil {
		return fmt.Errorf("attach DuckLake: %w", err)
	}
	log.Printf("DuckLake attached (catalog=PostgreSQL, data=%s)", dataPath)

	// Use analytics as default database
	if _, err := duckDB.Exec("USE analytics;"); err != nil {
		return fmt.Errorf("USE analytics: %w", err)
	}

	// Also attach main Safecast PostgreSQL for cross-database queries (read-only)
	databaseURL := os.Getenv("DATABASE_URL")
	if databaseURL == "" {
		// Unified server uses -db-conn flag; construct URL from that
		// Fall back to environment variable
	}
	if databaseURL != "" {
		if err := attachPostgres(databaseURL); err != nil {
			log.Printf("Warning: PostgreSQL attach failed: %v (cross-db analytics disabled)", err)
		} else {
			log.Println("Safecast PostgreSQL attached for cross-database queries")
		}
	}

	// Create analytics schema in DuckLake
	if err := createDuckDBSchema(); err != nil {
		log.Printf("Warning: failed to create DuckLake schema: %v", err)
	}

	return nil
}

// attachPostgres attaches the main Safecast PostgreSQL for read-only cross-database queries
func attachPostgres(databaseURL string) error {
	attachStr := databaseURL
	if !strings.Contains(databaseURL, "?") {
		attachStr = databaseURL + "?sslmode=prefer"
	}

	query := fmt.Sprintf("ATTACH '%s' AS postgres_db (TYPE POSTGRES, READ_ONLY);", attachStr)
	if _, err := duckDB.Exec(query); err != nil {
		return fmt.Errorf("attach postgres: %w", err)
	}
	return nil
}

// createDuckDBSchema creates the shared analytics tables in DuckLake
func createDuckDBSchema() error {
	// DuckLake doesn't support multi-statement exec, so run each separately
	tables := []string{
		`CREATE TABLE IF NOT EXISTS mcp_query_log (
			tool_name VARCHAR,
			timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
			duration_ms BIGINT,
			result_count INTEGER,
			client VARCHAR,
			user_id VARCHAR,
			user_email VARCHAR
		)`,
		`CREATE TABLE IF NOT EXISTS mcp_ai_query_log (
			user_id VARCHAR,
			user_email VARCHAR,
			session_id VARCHAR,
			timestamp TIMESTAMP,
			tool_name VARCHAR,
			generated_query VARCHAR,
			duration_ms BIGINT,
			commit_hash VARCHAR,
			error VARCHAR
		)`,
		`CREATE SEQUENCE IF NOT EXISTS seq_chat_questions START 1`,
		`CREATE TABLE IF NOT EXISTS chat_questions (
			id BIGINT DEFAULT nextval('seq_chat_questions'),
			timestamp TIMESTAMPTZ DEFAULT now(),
			question VARCHAR,
			source VARCHAR,
			ip_address VARCHAR,
			user_agent VARCHAR,
			is_mobile BOOLEAN,
			os VARCHAR,
			browser VARCHAR,
			country VARCHAR,
			accept_language VARCHAR,
			referer VARCHAR,
			session_id VARCHAR,
			history_length INTEGER,
			model VARCHAR,
			cloudfront BOOLEAN,
			client_timestamp TIMESTAMPTZ,
			answer VARCHAR
		)`,
	}

	for _, ddl := range tables {
		if _, err := duckDB.Exec(ddl); err != nil {
			return fmt.Errorf("create schema: %w", err)
		}
	}

	log.Println("DuckLake analytics schema ready")
	return nil
}

// duckDBAvailable returns true if DuckDB is initialized
func duckDBAvailable() bool {
	return duckDB != nil
}

