317→      <textarea id="msg" rows="1" placeholder="Ask about radiation levels, sensors, or locations…"></textarea>
318→      <button id="send" type="submit" title="Send">
319→        <svg width="18" height="18" viewBox="0 0 24 24"><path d="M2 21l21-9L2 3v7l15 2-15 2z"/></svg>
