325→<script>
326→  const messagesEl = document.getElementById('messages');
327→  const introEl    = document.getElementById('intro');
328→  const formEl     = document.getElementById('form');
329→  const msgEl      = document.getElementById('msg');
330→  const sendBtn    = document.getElementById('send');
331→
332→  let busy = false;
333→  let conversationHistory = []; // Track conversation for context
334→
335→  // Auto-grow textarea
336→  msgEl.addEventListener('input', () => {
337→    msgEl.style.height = 'auto';
338→    msgEl.style.height = Math.min(msgEl.scrollHeight, 120) + 'px';
339→  });
340→
341→  // Send on Enter (Shift+Enter = newline)
342→  msgEl.addEventListener('keydown', e => {
343→    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); submit(); }
344→  });
345→
346→  formEl.addEventListener('submit', submit);
347→
348→  function ask(chip) {
349→    msgEl.value = chip.textContent;
350→    submit();
351→  }
352→
353→  function submit() {
354→    const text = msgEl.value.trim();
355→    if (!text || busy) return;
356→    sendMessage(text);
357→    msgEl.value = '';
358→    msgEl.style.height = 'auto';
359→  }
360→
361→  // Convert markdown to HTML
362→  function markdownToHTML(text) {
363→    let html = text;
364→
365→    // Headers (must be at start of line)
366→    html = html.replace(/^### (.+)$/gm, '<h3>$1</h3>');
367→    html = html.replace(/^## (.+)$/gm, '<h2>$1</h2>');
368→    html = html.replace(/^# (.+)$/gm, '<h1>$1</h1>');
369→
370→    // Horizontal rules
371→    html = html.replace(/^---+$/gm, '<hr>');
372→
373→    // Tables (simple approach - detect table rows)
374→    html = html.replace(/^\|(.+)\|$/gm, function(match, content) {
375→      const cells = content.split('|').map(c => c.trim());
376→      const cellTags = cells.map(c => {
377→        // Check if this is a separator row (--|---|---)
378→        if (/^:?-+:?$/.test(c)) return null;
379→        return `<td>${c}</td>`;
380→      }).filter(Boolean);
381→      if (cellTags.length === 0) return '';
382→      return '<tr>' + cellTags.join('') + '</tr>';
383→    });
384→    // Wrap table rows in table tags
385→    html = html.replace(/(<tr>.+<\/tr>\n?)+/g, '<table>$&</table>');
386→
387→    // Unordered lists (lines starting with - or *)
388→    html = html.replace(/^[*-] (.+)$/gm, '<li>$1</li>');
389→    html = html.replace(/(<li>.+<\/li>\n?)+/g, '<ul>$&</ul>');
390→
391→    // Ordered lists (lines starting with 1., 2., etc)
392→    html = html.replace(/^\d+\. (.+)$/gm, '<li>$1</li>');
393→
394→    // Bold: **text** or __text__
395→    html = html.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
396→    html = html.replace(/__(.+?)__/g, '<strong>$1</strong>');
397→
398→    // Italic: *text* or _text_
399→    html = html.replace(/\*(.+?)\*/g, '<em>$1</em>');
400→    html = html.replace(/_(.+?)_/g, '<em>$1</em>');
401→
402→    // Inline code: `code`
403→    html = html.replace(/`(.+?)`/g, '<code>$1</code>');
404→
405→    // Links: [text](url) - do this BEFORE auto-linking plain URLs
406→    html = html.replace(/\[(.+?)\]\((.+?)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>');
407→
408→    // Auto-link plain URLs (but not ones already in <a> tags)
409→    html = html.replace(/(^|[^"'>])(https?:\/\/[^\s<]+)/g, function(match, prefix, url) {
410→      // Don't link if it's already inside an href attribute
411→      return prefix + '<a href="' + url + '" target="_blank" rel="noopener">' + url + '</a>';
412→    });
413→
414→    // Line breaks: preserve newlines, but not after block elements or between table rows
415→    html = html.replace(/\n/g, (match, offset, string) => {
416→      // Don't add <br> after closing block tags
417→      const beforeContext = string.substring(Math.max(0, offset - 50), offset);
418→      if (/<\/(table|ul|h[123]|tr)>\s*$/.test(beforeContext)) return '';
419→      // Don't add <br> before opening table rows
420→      const afterContext = string.substring(offset + 1, Math.min(string.length, offset + 10));
421→      if (/^\s*<tr>/.test(afterContext)) return '';
422→      return '<br>';
423→    });
424→
425→    return html;
426→  }
427→
428→  function addMessage(role, text, cls) {
429→    if (introEl) introEl.style.display = 'none';
430→
431→    const msg    = document.createElement('div');
432→    msg.className = `msg ${role}`;
433→
434→    const avatar = document.createElement('div');
435→    avatar.className = 'avatar';
436→    if (role === 'user') {
437→      avatar.textContent = '👤';
438→    } else {
439→      const img = document.createElement('img');
440→      img.src = 'safecast-square-ct.png';
441→      img.alt = 'Safecast';
442→      avatar.appendChild(img);
443→    }
444→
445→    const bubble = document.createElement('div');
446→    bubble.className = `bubble ${cls || ''}`;
447→    // User messages are plain text, bot messages support markdown
448→    if (role === 'bot') {
449→      bubble.innerHTML = markdownToHTML(text);
450→
451→      // Add copy button for bot messages
452→      const copyBtn = document.createElement('button');
453→      copyBtn.className = 'copy-btn';
454→      copyBtn.textContent = 'Copy';
455→      copyBtn.onclick = () => copyMessage(text, copyBtn);
456→      bubble.appendChild(copyBtn);
457→    } else {
458→      bubble.textContent = text;
459→    }
460→
461→    msg.appendChild(avatar);
462→    msg.appendChild(bubble);
463→    messagesEl.appendChild(msg);
464→    messagesEl.scrollTop = messagesEl.scrollHeight;
465→    return bubble;
466→  }
467→
468→  function copyMessage(text, btn) {
469→    navigator.clipboard.writeText(text).then(() => {
470→      const originalText = btn.textContent;
471→      btn.textContent = 'Copied!';
472→      btn.classList.add('copied');
473→      setTimeout(() => {
474→        btn.textContent = originalText;
475→        btn.classList.remove('copied');
476→      }, 2000);
477→    }).catch(err => {
478→      console.error('Failed to copy:', err);
479→    });
480→  }
481→
482→  function downloadConversation() {
483→    if (conversationHistory.length === 0) {
484→      alert('No conversation to download yet!');
485→      return;
486→    }
487→
488→    // Build markdown format
489→    let markdown = '# Safecast Radiation Assistant Conversation\n\n';
490→    markdown += `Date: ${new Date().toLocaleString()}\n\n`;
491→    markdown += '---\n\n';
492→
493→    conversationHistory.forEach(msg => {
494→      const role = msg.role === 'user' ? 'You' : 'Assistant';
495→      markdown += `## ${role}\n\n`;
496→      markdown += msg.content + '\n\n';
497→      markdown += '---\n\n';
498→    });
499→
500→    // Create download link
501→    const blob = new Blob([markdown], { type: 'text/markdown' });
502→    const url = URL.createObjectURL(blob);
503→    const a = document.createElement('a');
504→    a.href = url;
505→    a.download = `safecast-conversation-${new Date().toISOString().slice(0,10)}.md`;
506→    document.body.appendChild(a);
507→    a.click();
508→    document.body.removeChild(a);
509→    URL.revokeObjectURL(url);
510→  }
511→
512→  function clearConversation() {
513→    // Clear conversation history
514→    conversationHistory = [];
515→
516→    // Clear all messages
517→    while (messagesEl.firstChild) {
518→      messagesEl.removeChild(messagesEl.firstChild);
519→    }
520→
521→    // Show intro again
522→    messagesEl.appendChild(introEl);
523→    introEl.style.display = 'block';
524→
525→    // Focus on input
526→    msgEl.focus();
527→  }
528→
529→  function sendMessage(text) {
530→    busy = true;
531→    sendBtn.disabled = true;
532→
533→    addMessage('user', text);
534→    const botBubble = addMessage('bot', '…thinking…', 'thinking');
535→
536→    let accumulated = '';
537→
538→    function finish(success = true) {
539→      botBubble.classList.remove('thinking');
540→      busy = false;
541→      sendBtn.disabled = false;
542→      msgEl.focus();
543→
544→      // Add AI disclaimer to successful bot messages
545→      if (success && accumulated) {
546→        // Re-render with disclaimer
547→        const disclaimerText = '\n\n---\n\n_Note: AI-generated response using data from the Safecast radiation monitoring network. For critical safety decisions, please consult official sources._';
548→        botBubble.innerHTML = markdownToHTML(accumulated + disclaimerText);
549→
550→        // Re-add copy button (since we replaced innerHTML)
551→        const copyBtn = document.createElement('button');
552→        copyBtn.className = 'copy-btn';
553→        copyBtn.textContent = 'Copy';
554→        copyBtn.onclick = () => copyMessage(accumulated, copyBtn); // Copy without disclaimer
555→        botBubble.appendChild(copyBtn);
556→
557→        conversationHistory.push(
558→          { role: 'user', content: text },
559→          { role: 'assistant', content: accumulated }
560→        );
561→
562→        // Keep only last 10 messages (5 exchanges) to prevent rate limits
563→        const MAX_HISTORY = 10;
564→        if (conversationHistory.length > MAX_HISTORY) {
565→          conversationHistory = conversationHistory.slice(-MAX_HISTORY);
566→        }
567→      }
568→    }
569→
570→    fetch('/chat', {
571→      method: 'POST',
572→      headers: { 'Content-Type': 'application/json' },
573→      body: JSON.stringify({
574→        message: text,
575→        history: conversationHistory
576→      }),
577→    }).then(response => {
578→      const reader  = response.body.getReader();
579→      const decoder = new TextDecoder();
580→      let   buffer  = '';
581→
582→      function pump() {
583→        return reader.read().then(({ done, value }) => {
584→          if (done) { finish(); return; }
585→
586→          buffer += decoder.decode(value, { stream: true });
587→          const lines = buffer.split('\n');
588→          buffer = lines.pop(); // keep incomplete last line
589→
590→          for (const line of lines) {
591→            if (!line.trim()) continue;
592→            try {
593→              const ev = JSON.parse(line);
594→              if (ev.type === 'text') {
595→                if (botBubble.classList.contains('thinking')) {
596→                  botBubble.classList.remove('thinking');
597→                  accumulated = '';
598→                }
599→                accumulated += ev.text;
600→                botBubble.innerHTML = markdownToHTML(accumulated);
601→                messagesEl.scrollTop = messagesEl.scrollHeight;
602→              } else if (ev.type === 'done') {
603→                finish();
604→              } else if (ev.type === 'error') {
605→                botBubble.classList.remove('thinking');
606→                botBubble.classList.add('error');
607→                botBubble.textContent = 'Error: ' + ev.error;
608→                finish(false);
609→              }
610→            } catch { /* malformed line, skip */ }
611→          }
612→          return pump();
613→        });
614→      }
615→      return pump();
616→    }).catch(err => {
617→      botBubble.classList.remove('thinking');
618→      botBubble.classList.add('error');
619→      botBubble.textContent = 'Connection error: ' + err.message;
620→      finish(false);
621→    });
622→  }
623→
624→  msgEl.focus();
625→</script>
626→</body>
627→</html>
